import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"Back up your business and verify independent recovery","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/backup-restore","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/backup-restore.md","filePath":"en/tutorials/backup-restore.md"}'),n={name:"en/tutorials/backup-restore.md"};function r(o,e,d,c,p,l){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="back-up-your-business-and-verify-independent-recovery" tabindex="-1">Back up your business and verify independent recovery <a class="header-anchor" href="#back-up-your-business-and-verify-independent-recovery" aria-label="Permalink to &quot;Back up your business and verify independent recovery&quot;">​</a></h1><p>After deployment, prove that business data, Files objects and queued tasks can recover together. A Backup Archive contains a consistent database snapshot, verified ready objects, a manifest and reports from a Maintenance Window. Document exports and direct volume copies cannot replace it.</p><p>This guide requires a deployed production stack, Docker Compose, a protected environment file and enough archive space. Run commands from the repository root. Backup stops application writers; restoration creates new persistent volumes.</p><h2 id="include-your-business-in-the-backup-contract" tabindex="-1">Include your business in the backup contract <a class="header-anchor" href="#include-your-business-in-the-backup-contract" aria-label="Permalink to &quot;Include your business in the backup contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data location</th><th>Backup responsibility</th></tr></thead><tbody><tr><td>Business schemas in this deployment&#39;s PostgreSQL</td><td>Included in the full database dump with migration history, Sessions, Jobs and Audit</td></tr><tr><td>Ready objects published through Files</td><td>Verified against keys, sizes and sha256 in <code>saas_core.files</code>, then downloaded into the archive</td></tr><tr><td>Pending uploads</td><td>Staging objects are omitted; restored uploads expire by TTL and run idempotent cleanup</td></tr><tr><td>Additional databases or direct object writes</td><td>Not covered by these tools; extend manifest, verification and drills before promising recovery</td></tr><tr><td>Secrets and deployment configuration</td><td>Omitted; supplied separately through protected deployment configuration</td></tr></tbody></table><p>Use Files to manage file state, immutable content and ownership. The archive contains business data from PostgreSQL, so it still needs access control and retention despite excluding deployment secrets.</p><h2 id="stop-writes-drain-and-archive" tabindex="-1">Stop writes, drain and archive <a class="header-anchor" href="#stop-writes-drain-and-archive" aria-label="Permalink to &quot;Stop writes, drain and archive&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>Use the second positional argument for a chosen archive directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/release-before-upgrade</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/production-backup.mjs" target="_blank" rel="noreferrer">backup script</a> first stops API, requiring <code>draining HTTP requests</code> and exit before 25 seconds, below Compose&#39;s 30-second grace period. It then stops Worker, requiring <code>stopping worker claims and draining current work</code> and exit before 40 seconds, below its 45-second grace period. Reaching either budget or failed object verification fails the backup. Queued Jobs remain in PostgreSQL and are not claimed during the window.</p><p>After writers stop, the tool runs <code>pg_dump -Fc</code>, reads registered ready files, downloads each and verifies sha256 and size. Extra unreferenced objects are reported; missing or mismatched ready objects make the archive inconsistent.</p><p>Expect:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>database.dump</span></span>
<span class="line"><span>manifest.json</span></span>
<span class="line"><span>objects/</span></span>
<span class="line"><span>backup-report.md</span></span></code></pre></div><p><code>manifest.json</code> records the image/digest, migration version and object inventory. After checking PASS and its details, restart the original stack with <code>just production-up .env.production</code>.</p><h2 id="restore-into-an-independent-empty-environment" tabindex="-1">Restore into an independent empty environment <a class="header-anchor" href="#restore-into-an-independent-empty-environment" aria-label="Permalink to &quot;Restore into an independent empty environment&quot;">​</a></h2><p>Stop the production composition to release 80/443 while preserving its volumes:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/release-before-upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>The Restore Environment gets a different Compose project name, new network and new volumes. The tool rejects the production project name. Releasing production ports does not require deleting production data. Switching traffic is an explicit deployment decision; the tool does not overwrite production volumes.</p><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/production-restore.mjs" target="_blank" rel="noreferrer">restore script</a> starts dependencies, runs <code>pg_restore --no-owner --exit-on-error</code>, initializes the bucket, starts Caddy, uploads manifest objects, then starts API/Worker. Prepare the archive&#39;s matching image and protected configuration: it does not download historical images or implicitly apply new migrations.</p><p>Final checks cover readiness, migration version and bucket inventory. It writes <code>restore-report.md</code> and leaves the stack running for inspection. A failed <code>pg_restore</code> may have partially written the target; remove that failed independent restore project and create a fresh one before retrying.</p><h2 id="add-recovery-assertions-for-your-business" tabindex="-1">Add recovery assertions for your business <a class="header-anchor" href="#add-recovery-assertions-for-your-business" aria-label="Permalink to &quot;Add recovery assertions for your business&quot;">​</a></h2><p>After structural verification, use the real HTTPS API to validate a complete business result:</p><ol><li>Before backup, create a resource with known fields and record its id, version and authorized account.</li><li>Publish a file with known bytes if the business uses files.</li><li>Stop Worker, then enqueue a task through the public API before backup.</li><li>After restore, sign in or use the restored Session; compare resource fields, version and file bytes.</li><li>Wait for Worker to complete the original queued Job and read its business result. Verify failures/revocation do not publish extra objects.</li><li>In the drill, expire a pending upload and check its terminal state and staging cleanup.</li></ol><p>The existing <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/scripts/production-restore-drill.mjs" target="_blank" rel="noreferrer">automated drill</a> exercises the same backup/restore commands with the reference application: account, documents, attachment bytes, queued export, pending expiry and cleanup. It creates test projects and secrets, removes its volumes, environment files and temporary certificate afterward, and keeps reports in <code>.scratch/</code>. It needs free 80/443 ports. Add your business assertions explicitly; they are not automatically part of this journey.</p><h2 id="checks-and-recovery" tabindex="-1">Checks and recovery <a class="header-anchor" href="#checks-and-recovery" aria-label="Permalink to &quot;Checks and recovery&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-sigv4.test.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/backup-manifest.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore-drill</span></span></code></pre></div><p>Manifest and SigV4 tests require no Docker; the drill runs the real production stack. Identify the process holding conflicting ports before proceeding; volume deletion is not a port-conflict remedy. Preserve reports for object mismatches and compare Files records with storage. Recover missing deployment secrets from protected configuration; they cannot be derived from the archive.</p><p>These tools belong to SaaS Core and survive reference application removal. Next: <a href="./../testing/feedback-loop">Integrate your recovery assertions into the feedback loop</a>.</p><hr><p>Source version：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/tutorials/22-backup-restore.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,31)])])}const b=t(n,[["render",r]]);export{u as __pageData,b as default};
